body { font-family: system-ui; padding: 24px; }
.box { position: relative; width: 120px; padding: 16px; margin: 12px 0; color: #fff; border-radius: 8px; background: #2563eb; }
.janky { transition: left .4s; left: 0; }
.janky:hover { left: 200px; }
.smooth { transition: transform .4s; }
.smooth:hover { transform: translateX(200px); }

body { font-family: system-ui; padding: 24px; }
.card {
  content-visibility: auto;
  contain-intrinsic-size: 0 400px;
  height: 400px;
  margin-bottom: 16px;
  background: #e0e7ff;
  display: grid; place-items: center;
  border-radius: 12px;
}

body { font-family: system-ui; padding: 24px; }
.panel {
  position: fixed; top: 0; left: -260px;
  width: 240px; height: 100vh;
  background: #1e293b; color: #fff; padding: 20px;
  /* TODO: animate with transform, not left */
  transition: left .3s;
}
.panel.open { left: 0; }

body { font-family: system-ui; padding: 24px; }
.panel {
  position: fixed; top: 0; left: 0;
  width: 240px; height: 100vh;
  background: #1e293b; color: #fff; padding: 20px;
  transform: translateX(-100%);
  transition: transform .3s;
}
.panel.open { transform: translateX(0); }

body { font-family: system-ui; padding: 40px; }
.card {
  width: 200px; height: 120px;
  background: #2563eb; color: #fff;
  display: grid; place-items: center; border-radius: 12px;
  transition: width .3s, height .3s;
}
.card:hover { width: 240px; height: 150px; }

body { font-family: system-ui; padding: 40px; }
.card {
  width: 200px; height: 120px;
  background: #2563eb; color: #fff;
  display: grid; place-items: center; border-radius: 12px;
  transition: transform .3s;
}
.card:hover { transform: scale(1.2); }

